/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Clearing an assignee publishes `issue.unassigned`
 * (and nothing when the issue was already unassigned). `issue.assigned`
 * carries a non-null assignee by contract, so a hand-off from one person to
 * another stays that event alone.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    if (before.assigneeId !== null) {
      await emitUnassigned(actor, after, before.assigneeId);
    }
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

/**
 * Drops a departing member from every live issue still assigned to them.
 * Archived issues keep their assignee. One `issue.unassigned` per issue, with
 * the remover as the actor. Called from member removal; authorization for
 * that action is the caller's responsibility.
 */
export async function unassignLiveIssuesForUser(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const issues = await issueRepo.listLiveIssuesByAssignee(orgId, userId);
  for (const issue of issues) {
    if (issue.assigneeId === null) continue;
    await issueRepo.setIssueAssignee(orgId, issue.id, null);
    await emitUnassigned(actor, issue, issue.assigneeId);
  }
}

async function emitUnassigned(
  actor: Actor,
  issue: Pick<Issue, "id" | "projectId">,
  previousAssigneeId: UserId,
): Promise<void> {
  await emit("issue.unassigned", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    previousAssigneeId,
  });
}

